public final class RssiFilter { private final ArrayDeque<Integer> q=new ArrayDeque<>(); private ProximityBucket current=ProximityBucket.UNKNOWN,pending=ProximityBucket.UNKNOWN; private int pendingCount=0; public synchronized ProximityBucket add(int rssi){q.addLast(rssi);while(q.size()>7)q.removeFirst();if(q.size()<4)return current=ProximityBucket.UNKNOWN;int[]a=new int[q.size()];int i=0;for(int x:q)a[i++]=x;Arrays.sort(a);int m=a[a.length/2];ProximityBucket b=m>=-50?ProximityBucket.VERY_CLOSE:m>=-67?ProximityBucket.NEAR:m>=-78?ProximityBucket.MID:ProximityBucket.FAR;if(b==current){pending=b;pendingCount=0;return current;}if(b==pending)pendingCount++;else{pending=b;pendingCount=1;}if(pendingCount>=2){current=b;pendingCount=0;}return current;} public synchronized ProximityBucket bucket(){return current;} public synchronized int sampleCount(){return q.size();} }
